// Login function to test
function authenticateUser(username, password) {
  const user = findUserByUsername(username);
  if (!user) return { success: false, error: 'User not found' };

  const isValid = bcrypt.compareSync(password, user.passwordHash);
  if (!isValid) return { success: false, error: 'Invalid password' };

  return { success: true, user: { id: user.id, username: user.username } };
}

// Unit test (using Jest)
describe('authenticateUser', () => {
  test('returns user object for valid credentials', () => {
    const result = authenticateUser('john@example.com', 'correct-password');
    expect(result.success).toBe(true);
    expect(result.user.username).toBe('john@example.com');
  });

  test('returns error for invalid password', () => {
    const result = authenticateUser('john@example.com', 'wrong-password');
    expect(result.success).toBe(false);
    expect(result.error).toBe('Invalid password');
  });

  test('returns error for non-existent user', () => {
    const result = authenticateUser('unknown@example.com', 'any-password');
    expect(result.success).toBe(false);
    expect(result.error).toBe('User not found');
  });
});

