public class FraudCheckDecorator : IPaymentProcessor
{
    private readonly IPaymentProcessor _inner;
    private readonly IFraudService _fraudService;

    public FraudCheckDecorator(IPaymentProcessor inner, IFraudService fraudService)
    {
        _inner = inner;
        _fraudService = fraudService;
    }

    public bool ProcessPayment(decimal amount, string creditCardNumber)
    {
        // New fraud check feature, developed with TDD
        if (_fraudService.IsSuspicious(amount, creditCardNumber))
        {
            _fraudService.LogSuspiciousActivity(amount, creditCardNumber);
            return false;
        }

        return _inner.ProcessPayment(amount, creditCardNumber);
    }
}

