[Test]
public void FraudCheckDecorator_BlocksSuspiciousTransactions()
{
    var mockInner = new Mock<IPaymentProcessor>();
    var mockFraud = new Mock<IFraudService>();
    mockFraud.Setup(f => f.IsSuspicious(5000m, "1234"))
             .Returns(true);

    var decorator = new FraudCheckDecorator(mockInner.Object, mockFraud.Object);

    var result = decorator.ProcessPayment(5000m, "1234");

    Assert.IsFalse(result);
    mockInner.Verify(i => i.ProcessPayment(It.IsAny<decimal>(), It.IsAny<string>()), 
                     Times.Never);
}

