const request = require('supertest');
const app = require('../../src/app');
const { testData } = require('../helpers/test-data');

describe('Orders API', () => {
  let authToken;
  let testUser;

  beforeEach(async () => {
    // Create fresh test user for each test
    testUser = await testData.createUser();
    authToken = await testData.getAuthToken(testUser);
  });

  afterEach(async () => {
    await testData.cleanupUser(testUser);
  });

  describe('POST /api/orders', () => {
    test('creates order with valid data', async () => {
      const orderData = {
        items: [
          { productId: 'prod_123', quantity: 2 },
          { productId: 'prod_456', quantity: 1 }
        ],
        shippingAddress: {
          street: '123 Main St',
          city: 'Boston',
          zip: '02101'
        },
        paymentMethod: 'credit_card'
      };

      const response = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${authToken}`)
        .send(orderData)
        .expect(201);

      // Validate response structure
      expect(response.body).toHaveProperty('orderId');
      expect(response.body).toHaveProperty('total');
      expect(response.body.status).toBe('pending');

      // Verify order in database
      const order = await testData.getOrder(response.body.orderId);
      expect(order).toBeDefined();
      expect(order.items).toHaveLength(2);
    });

    test('validates required fields', async () => {
      const invalidOrder = {
        // Missing items
        shippingAddress: {
          street: '123 Main St',
          city: 'Boston',
          zip: '02101'
        }
      };

      const response = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${authToken}`)
        .send(invalidOrder)
        .expect(400);

      expect(response.body.error).toContain('items is required');
    });

    test('rejects unauthorized requests', async () => {
      await request(app)
        .post('/api/orders')
        .send({})
        .expect(401);
    });

    test('validates product availability', async () => {
      const orderWithUnavailable = {
        items: [
          { productId: 'prod_unavailable', quantity: 1 }
        ],
        shippingAddress: {
          street: '123 Main St',
          city: 'Boston',
          zip: '02101'
        }
      };

      const response = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${authToken}`)
        .send(orderWithUnavailable)
        .expect(400);

      expect(response.body.error).toContain('Product unavailable');
    });
  });

  describe('GET /api/orders/:id', () => {
    test('returns order for valid ID', async () => {
      // First create an order
      const order = await testData.createOrder(testUser.id);

      const response = await request(app)
        .get(`/api/orders/${order.id}`)
        .set('Authorization', `Bearer ${authToken}`)
        .expect(200);

      expect(response.body.id).toBe(order.id);
      expect(response.body.items).toBeDefined();
    });

    test('returns 404 for non-existent order', async () => {
      await request(app)
        .get('/api/orders/non-existent-id')
        .set('Authorization', `Bearer ${authToken}`)
        .expect(404);
    });

    test('returns 403 for order belonging to different user', async () => {
      // Create order for different user
      const otherUser = await testData.createUser();
      const order = await testData.createOrder(otherUser.id);

      await request(app)
        .get(`/api/orders/${order.id}`)
        .set('Authorization', `Bearer ${authToken}`) // Current user's token
        .expect(403);
    });
  });

  describe('Contract testing', () => {
    test('response matches OpenAPI schema', async () => {
      const response = await request(app)
        .get('/api/orders/schema')
        .expect(200);

      // Validate against OpenAPI spec
      const schema = require('../../specs/openapi.json');
      const validate = require('swagger-parser').validate;
      await validate(schema);
    });
  });
});

